for item in records:
    image = item.pop('image')
    item['images'] = [{"id": image, "src": f"images/batches/{image}.webp"}]
# Preserve familiar property order from other seed entries.
keys = ["appearanceLevel", "shortDescription", "focus", "images", "id", "title", "description", "tags", "priority", "status", "source", "origin"]
records = [{k: r[k] for k in keys} for r in records]
file = root / 'docs' / 'mechanics' / 'batch-seed.js'
text = file.read_text(encoding='utf-8-sig')
marker = '\n]);'
idx = text.rfind(marker)
assert idx >= 0 and 'base-b08-10' not in text
rendered = ',\n'.join('  ' + json.dumps(record, ensure_ascii=False, indent=2).replace('\n', '\n  ') for record in records)
updated = text[:idx].rstrip() + ',\n' + rendered + '\n]);\n'
file.write_text(updated, encoding='utf-8')
print(f'Appended {len(records)} entries to {file}')
